using System;
using System.Collections.Generic;
using System.Reflection;
using UnityEditor;
using UnityEngine;
using UnityEngine.UIElements;
using DCFApixels.WhimTex;

public class SoftRangeSmokeWindow : EditorWindow { }

public static class SoftRangeSmoke
{
    public static string Main()
    {
        const BindingFlags flags = BindingFlags.NonPublic | BindingFlags.Public | BindingFlags.Static | BindingFlags.Instance;
        var assembly=typeof(ShaderFX).Assembly;
        var metadata=assembly.GetType("DCFApixels.WhimTex.ShaderFXMetadata");
        List<ShaderFXParameter> Parse(string text)=>(List<ShaderFXParameter>)metadata.GetMethod("Parse",flags).Invoke(null,new object[]{text,false,null});
        void Check(bool ok,string message){if(!ok)throw new Exception(message);}
        const string code="// @param float _Strength = 1 [0 .. 2]\n// @param float _Strength [~0 .. ~2] // Soft control\nfloat4 ApplyFX(float2 uv,float4 color){return _Strength;}";
        var parsed=Parse(code);
        Check(parsed.Count==1 && !parsed[0].controls[0].softMaximum && parsed[0].controls[1].softMaximum,"Per-control range metadata");
        Check(Parse("// @param float _X = 5 [~0 .. ~2]")[0].floatValue==5,"Out-of-range default");
        Check(Parse("// @param float _X [~-2 .. ~2]")[0].floatValue==0,"Optional default");
        foreach(var bad in new[]{"// @param float _X [~0 ..]","// @param float _X [.. ~2]","// @param float _X [~2 .. 2]","// @param float _X [3 .. ~2]","// @param bool _X [~0 .. ~2]","// @param float _X [0 .. ~Infinity]", "// @param float _X ~[0 .. 2]", "// @param float _X [~ .. 2]"})
        {
            bool rejected=false;try{Parse(bad);}catch(TargetInvocationException e)when(e.InnerException is FormatException){rejected=true;}
            Check(rejected,"Accepted invalid soft range: "+bad);
        }
        ShaderFX fx=null; SoftRangeSmokeWindow window=null;
        var owner=ScriptableObject.CreateInstance<TextureCompositor>();owner.hideFlags=HideFlags.HideAndDontSave;
        try
        {
            fx=(ShaderFX)typeof(ShaderFX).GetMethod("CreateAgentDraft", flags, null, new[] { typeof(DCFApixels.WhimTex.TextureCompositor), typeof(string), typeof(List<DCFApixels.WhimTex.ShaderFXParameter>) }, null).Invoke(null,new object[]{owner,code,new List<ShaderFXParameter>()});
            typeof(ShaderFX).GetMethod("ApplyAgentDraft",flags).Invoke(fx,null);
            var values=(List<ShaderFXParameter>)typeof(ShaderFX).GetField("parameters",flags).GetValue(fx);
            var view=(VisualElement)Activator.CreateInstance(assembly.GetType("DCFApixels.WhimTex.ShaderFXParameterView"),flags,null,new object[]{fx},null);
            window=ScriptableObject.CreateInstance<SoftRangeSmokeWindow>();window.titleContent=new GUIContent("Soft range test");
            window.rootVisualElement.Add(view);window.ShowUtility();
            var soft=view.Q<VisualElement>(className:"whimtex-soft-range");
            var number=soft.Q<FloatField>();var slider=soft.Q<Slider>();
            var fieldType=soft.GetType();
            foreach(var lowerSoft in new[]{false,true})
            foreach(var upperSoft in new[]{false,true})
            {
                var side=(BaseField<float>)Activator.CreateInstance(fieldType,flags,null,new object[]{"Sides",0f,2f,lowerSoft,upperSoft},null);
                window.rootVisualElement.Add(side);
                var input=side.Q<FloatField>();
                input.value=-3;
                Check(side.value==(lowerSoft?-3:0) && input.value==side.value,"Independent lower boundary");
                input.value=5;
                Check(side.value==(upperSoft?5:2) && input.value==side.value,"Independent upper boundary");
                side.RemoveFromHierarchy();
                var declaration=Parse("// @param float _X ["+(lowerSoft?"~":"")+"0 .. "+(upperSoft?"~":"")+"2]")[0];
                Check(declaration.softMinimum==lowerSoft && declaration.softMaximum==upperSoft,"Boundary parsing");
                var clamp=typeof(ShaderFXParameter).GetMethod("Clamp",flags);
                Check((float)clamp.Invoke(declaration,new object[]{-3f})==(lowerSoft?-3:0) && (float)clamp.Invoke(declaration,new object[]{5f})==(upperSoft?5:2),"Per-boundary clamp");
            }
            number.value=5;
            Check(values[0].floatValue==5 && number.value==5 && slider.value==2,"Numeric input above range");
            number.value=-3;
            Check(values[0].floatValue==-3 && number.value==-3 && slider.value==0,"Numeric input below range");
            slider.value=1.5f;
            Check(values[0].floatValue==1.5f && number.value==1.5f,"Slider after outside input");
            var hard=view.Q<Slider>(); hard.value=.5f;hard.value=5;
            Check(values[0].floatValue==2,"Hard range still clamps");
            number.value=5;
            var context=Activator.CreateInstance(assembly.GetType("DCFApixels.WhimTex.LayerRenderContext"),owner,null,4,4,1f,true,true, null);
            var material=(Material)typeof(ShaderFX).GetMethod("GetMaterial",flags).Invoke(fx,new[]{context});
            Check(material.GetFloat("_Strength")==5,"GPU receives outside value");
            var writer=assembly.GetType("DCFApixels.WhimTex.ShaderFXPresetWriter");
            string exported=(string)writer.GetMethod("BuildSource",flags).Invoke(null,new object[]{fx,"Test/Soft"});
            Check(exported.Contains("_Strength [0 .. 2]") && exported.Contains("_Strength = 5 [~0 .. ~2] // Soft control"),"Export assigns the default to a compatible control without changing either range");
            var roundtrip=Parse(exported);Check(roundtrip[0].floatValue==5 && roundtrip[0].controls[1].softMaximum,"Export value/controls roundtrip");
            foreach (float value in new[] { -3f, 1f })
            {
                number.value=value;
                string next=(string)writer.GetMethod("BuildSource",flags).Invoke(null,new object[]{fx,"Test/Soft"});
                var restored=Parse(next)[0];
                Check(restored.floatValue==value && restored.controls.Count==2 &&
                    !restored.controls[0].softMinimum && !restored.controls[0].softMaximum &&
                    restored.controls[1].softMinimum && restored.controls[1].softMaximum,"Linked bounds/value preserved at "+value);
            }
            var copy=JsonUtility.FromJson<ShaderFXParameter>(JsonUtility.ToJson(values[0]));Check(copy.controls[1].softMaximum,"Serialization");
            var brushType=assembly.GetType("DCFApixels.WhimTex.BrushTipProgram");
            const string brush="// @whimtex-brush Test/Soft\n// @param float _Strength = 5 [~0 .. ~2]\nfloat4 BrushTip(float2 uv){return float4(_Strength,0,0,1);}";
            var brushValues=(List<ShaderFXParameter>)brushType.GetMethod("Parse",flags).Invoke(null,new object[]{brush,null});
            Check((float)typeof(ShaderFXParameter).GetMethod("Clamp",flags).Invoke(brushValues[0],new object[]{5f})==5,"Brush GPU clamp");
            string brushExport=(string)brushType.GetMethod("Export",flags).Invoke(null,new object[]{brush,brushValues});
            Check(brushExport.Contains("= 5 [~0 .. ~2]"),"Brush export");
            return "PASS: parsing/validation, attached UI typing and dragging, linked hard/soft controls, shader upload, FX/brush export and serialization.";
        }
        catch (TargetInvocationException e) { throw new Exception(e.GetBaseException().ToString()); }
        finally
        {
            if(window!=null)window.Close();
            if(fx!=null){Undo.ClearUndo(fx);UnityEngine.Object.DestroyImmediate(fx);}
            UnityEngine.Object.DestroyImmediate(owner);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;
using System.Threading.Tasks;
using UnityEditor;
using UnityEngine;
using UnityEngine.UIElements;
using DCFApixels.WhimTex;

// run_script entry: TwoChoiceDropdownSmoke.Main. Only an owned, empty utility window.
public class TwoChoiceDropdownSmokeWindow : EditorWindow { }

public static class TwoChoiceDropdownSmoke
{
    public enum LabeledChoice { [InspectorName("First Choice")] First = 4, Second = 12 }
    [Flags] public enum FlagChoice { First = 1, Second = 2 }

    public static async Task<string> Main()
    {
        var previousFocus = EditorWindow.focusedWindow;
        var window = ScriptableObject.CreateInstance<TwoChoiceDropdownSmokeWindow>();
        ShaderFX fx = null;
        int checks = 0;
        void Check(bool ok, string message) { if (!ok) throw new Exception(message); checks++; }
        try
        {
            window.ShowUtility();
            window.position = new Rect(100, 100, 420, 200);
            window.Focus();
            var field = new DropdownField("Dynamic choices", new List<string> { "A", "B" }, 0);
            window.rootVisualElement.Add(field);
            var input = field.Q<VisualElement>(className: DropdownField.inputUssClassName);
            Check(input != null, "Public input USS selector finds the dropdown input");
            var assembly = typeof(TextureCompositorWindow).Assembly;
            var type = assembly.GetType("DCFApixels.WhimTex.TwoChoiceDropdownManipulator`1", true).MakeGenericType(typeof(string));
            var manipulator = (IManipulator)Activator.CreateInstance(type, BindingFlags.Instance | BindingFlags.NonPublic,
                null, new object[] { input, (Func<IReadOnlyList<string>>)(() => field.choices),
                    (Func<string>)(() => field.value), (Action<string>)(v => field.value = v), (Func<string, string>)(v => v) }, null);
            field.AddManipulator(manipulator);
            await Task.Delay(100);
            int changes = 0;
            field.RegisterValueChangedCallback(_ => changes++);
            int Pointer() => (int)type.GetField("pointer", BindingFlags.Instance | BindingFlags.NonPublic).GetValue(manipulator);
            void Down(int button = 0)
            {
                using var evt = PointerDownEvent.GetPooled(new Event
                    { type = EventType.MouseDown, button = button, mousePosition = input.worldBound.center });
                evt.target = input;
                input.SendEvent(evt);
            }
            void Up(bool inside = true)
            {
                using var evt = PointerUpEvent.GetPooled(new Event { type = EventType.MouseUp, button = 0,
                    mousePosition = inside ? input.worldBound.center : new Vector2(-20, -20) });
                evt.target = input;
                input.SendEvent(evt);
            }
            void Escape()
            {
                using var evt = KeyDownEvent.GetPooled(new Event { type = EventType.KeyDown, keyCode = KeyCode.Escape });
                field.SendEvent(evt);
            }
            Down(); Check(Pointer() >= 0, "Two choices arm short-click handling"); Up();
            Check(field.value == "B" && changes == 1, "Short click changes the value exactly once");
            Check(Pointer() == -1 && !field.HasPointerCapture(PointerId.mousePointerId), "Release clears capture");
            Down(); Up(); Check(field.value == "A" && changes == 2, "Second click toggles back");
            Down();
            var drag = type.GetMethod("IsDownwardDrag", BindingFlags.Instance | BindingFlags.NonPublic);
            bool Opens(float x, float y) => (bool)drag.Invoke(manipulator, new object[] { input.worldBound.center + new Vector2(x, y) });
            Check(!Opens(0, 0) && !Opens(0, 3), "Small pointer jitter does not request a menu");
            Check(Opens(0, 4), "Downward drag requests menu at four UI pixels without waiting");
            Check(Opens(0, input.worldBound.height + 10), "Downward drag remains valid below the input");
            Check(Opens(5, 5), "Diagonal downward movement also requests menu");
            Check(!Opens(0, -10) && !Opens(10, 0), "Upward and sideways movement do not request menu");
            Escape();
            Down(); Escape(); Up(); Check(field.value == "A" && Pointer() == -1, "Escape cancels without applying");
            Down(); Up(false); Check(field.value == "A", "Outside release cancels");
            Down(); field.choices.Add("C"); Up(); Check(field.value == "A", "Mid-gesture choice count change cancels");
            // Call the package handler directly for native-fallback cases, so this automated test opens no OS menu.
            void ProbeDown()
            {
                using var evt = PointerDownEvent.GetPooled(new Event
                    { type = EventType.MouseDown, button = 0, mousePosition = input.worldBound.center });
                type.GetMethod("OnDown", BindingFlags.Instance | BindingFlags.NonPublic).Invoke(manipulator, new object[] { evt });
            }
            ProbeDown(); Check(Pointer() == -1, "Three choices leave native behavior untouched");
            field.choices.RemoveAt(2);
            Down(); Up(); Check(field.value == "B", "Returning to two choices activates automatically");
            Down(); field.choices = new List<string> { "X", "Y" }; Up();
            Check(field.value != "A", "Replacing two options does not apply an old option");
            field.choices = new List<string> { "A", "B" }; field.SetValueWithoutNotify("A");
            Down(); field.SetValueWithoutNotify("B"); Up(); Check(field.value == "B", "External value update is not overwritten");
            field.SetValueWithoutNotify(""); ProbeDown(); Check(Pointer() == -1, "Mixed/unknown value falls back to menu");
            field.SetValueWithoutNotify("A"); field.SetEnabled(false); ProbeDown();
            Check(Pointer() == -1, "Disabled control does not arm"); field.SetEnabled(true);
            Down(); field.SetEnabled(false); Up(); Check(field.value == "A", "Disabled during gesture cancels"); field.SetEnabled(true);
            Down(); field.RemoveFromHierarchy(); Check(Pointer() == -1, "Detach cancels the scheduled hold");
            window.rootVisualElement.Add(field);
            await Task.Delay(350);
            Check(Pointer() == -1 && field.value == "A", "Cancelled hold stays cancelled after reattach");
            Down(); field.RemoveManipulator(manipulator); Check(Pointer() == -1, "Removing manipulator releases capture");

            var enumField = new EnumField("Color Range", LayerColorRange.Standard);
            window.rootVisualElement.Add(enumField);
            var attach = assembly.GetType("DCFApixels.WhimTex.TwoChoiceDropdown", true).GetMethod("Attach",
                BindingFlags.Static | BindingFlags.NonPublic, null, new[] { typeof(EnumField) }, null);
            attach.Invoke(null, new object[] { enumField });
            await Task.Delay(100);
            var enumInput = enumField.Q<VisualElement>(className: EnumField.inputUssClassName);
            Check(enumInput != null, "Public input USS selector finds the enum input");
            using (var evt = PointerDownEvent.GetPooled(new Event { type = EventType.MouseDown, button = 0, mousePosition = enumInput.worldBound.center }))
            { evt.target = enumInput; enumInput.SendEvent(evt); }
            using (var evt = PointerUpEvent.GetPooled(new Event { type = EventType.MouseUp, button = 0, mousePosition = enumInput.worldBound.center }))
            { evt.target = enumInput; enumInput.SendEvent(evt); }
            Check(Equals(enumField.value, LayerColorRange.HDR), "Enum adapter toggles Standard to HDR");
            const BindingFlags flags = BindingFlags.Static | BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public;
            var adapter = assembly.GetType("DCFApixels.WhimTex.TwoChoiceDropdown", true);
            var attachAny = adapter.GetMethod("Attach", flags, null, new[] { typeof(VisualElement) }, null);
            var attached = (System.Runtime.CompilerServices.ConditionalWeakTable<VisualElement, IManipulator>)adapter.GetField("attached", flags).GetValue(null);
            IManipulator Attached(VisualElement control) => attached.TryGetValue(control, out var result) ? result : null;
            object Choices(VisualElement control)
            {
                var handler = Attached(control);
                return ((Delegate)handler.GetType().GetField("getChoices", flags).GetValue(handler)).DynamicInvoke();
            }
            void Click(VisualElement control)
            {
                var visualInput = control.Q<VisualElement>(className: BaseField<string>.inputUssClassName);
                Check(visualInput != null && visualInput.worldBound.width > 0, "Control has a laid-out input");
                using (var evt = PointerDownEvent.GetPooled(new Event { type = EventType.MouseDown, button = 0, mousePosition = visualInput.worldBound.center }))
                { evt.target = visualInput; visualInput.SendEvent(evt); }
                using (var evt = PointerUpEvent.GetPooled(new Event { type = EventType.MouseUp, button = 0, mousePosition = visualInput.worldBound.center }))
                { evt.target = visualInput; visualInput.SendEvent(evt); }
            }
            var originalHandler = Attached(enumField);
            attachAny.Invoke(null, new object[] { enumField });
            Check(ReferenceEquals(originalHandler, Attached(enumField)), "Repeated configuration does not install another handler");
            enumField.showMixedValue = true;
            Check(Choices(enumField) == null, "Mixed enum does not toggle an arbitrary selection");
            enumField.showMixedValue = false;
            enumField.Init(LabeledChoice.First);
            var enumChoices = (IReadOnlyList<Enum>)Choices(enumField);
            Check(enumChoices.Count == 2 && Equals(enumChoices[1], LabeledChoice.Second), "Enum Init refreshes cached type and nonconsecutive values");
            var label = (Delegate)originalHandler.GetType().GetField("getLabel", flags).GetValue(originalHandler);
            Check((string)label.DynamicInvoke(LabeledChoice.First) == "First Choice", "InspectorName survives the held menu");
            enumField.Init(FlagChoice.First);
            Check(Choices(enumField) == null, "Flags retain native behavior");

            window.rootVisualElement.Clear();
            window.position = new Rect(100, 100, 420, 500);
            var popup = new PopupField<int>("Mip", new List<int> { 0, 1 }, 0, v => "Mip " + v, v => "Mip " + v);
            window.rootVisualElement.Add(popup);
            attachAny.Invoke(null, new object[] { popup });
            var nullChoice = new NoiseLayerBehaviour().Owner;
            var layerPopup = new PopupField<Layer>("Layer", new List<Layer> { null, nullChoice }, 0, v => v == null ? "None" : "Layer", v => v == null ? "None" : "Layer");
            window.rootVisualElement.Add(layerPopup);
            attachAny.Invoke(null, new object[] { layerPopup });
            await Task.Delay(100);
            Click(popup); Check(popup.value == 1, "Typed popup toggles and preserves values");
            var popupHandler = Attached(popup);
            var popupLabel = (Delegate)popupHandler.GetType().GetField("getLabel", flags).GetValue(popupHandler);
            Check((string)popupLabel.DynamicInvoke(1) == "Mip 1", "Typed popup preserves its label formatter");
            popup.showMixedValue = true; Check(Choices(popup) == null, "Mixed typed popup retains native behavior");
            popup.showMixedValue = false;
            popup.choices.Add(2); Check(((IReadOnlyList<int>)Choices(popup)).Count == 3, "Adapter observes live option count");
            Click(layerPopup); Check(ReferenceEquals(layerPopup.value, nullChoice), "Layer popup accepts a null first choice");

            var configure = assembly.GetType("DCFApixels.WhimTex.WhimTexUI").GetMethod("ConfigureField", flags).MakeGenericMethod(typeof(EnumField));
            var standardField = new EnumField("Color", LayerColorRange.Standard);
            configure.Invoke(null, new object[] { standardField, 120f });
            Check(Attached(standardField) != null, "Shared field configuration installs the behavior");

            var parse = assembly.GetType("DCFApixels.WhimTex.ShaderFXMetadata").GetMethod("Parse", flags);
            var parameters = (List<ShaderFXParameter>)parse.Invoke(null, new object[] {
                "// @param enum _Body = A { A: 2, B: 7 }\n" +
                "// @group(Mode; _Mode)\n// @param hidden enum _Mode = A { A: 3, B: 9 }\n" +
                "// @if _Mode == 9\n// @param float _Amount = 1\n// @endif\n// @endgroup\n", false, null });
            fx = ScriptableObject.CreateInstance<ShaderFX>();
            fx.hideFlags = HideFlags.HideAndDontSave;
            typeof(ShaderFX).GetField("parameters", flags).SetValue(fx, parameters);
            float ParameterValue(int index) => ((List<ShaderFXParameter>)typeof(ShaderFX).GetField("parameters", flags).GetValue(fx))[index].floatValue;
            var viewType = assembly.GetType("DCFApixels.WhimTex.ShaderFXParameterView");
            var view = (VisualElement)Activator.CreateInstance(viewType, flags, null, new object[] { fx }, null);
            window.rootVisualElement.Add(view);
            var dropdowns = view.Query<DropdownField>().ToList();
            Check(dropdowns.Count == 2 && Attached(dropdowns[0]) != null && Attached(dropdowns[1]) != null,
                "FX body and group-header dropdowns are attached");
            await Task.Delay(100);
            Undo.IncrementCurrentGroup();
            Click(dropdowns[0]); Undo.FlushUndoRecordObjects();
            Check(ParameterValue(0) == 7, "FX body toggles to the declared numeric value");
            Undo.PerformUndo(); viewType.GetMethod("Refresh", flags).Invoke(view, null);
            dropdowns = view.Query<DropdownField>().ToList();
            Check(ParameterValue(0) == 2 && dropdowns[0].value == "A", "FX click Undo restores model and control: " + ParameterValue(0) + ", " + dropdowns[0].value);
            Undo.PerformRedo(); viewType.GetMethod("Refresh", flags).Invoke(view, null);
            dropdowns = view.Query<DropdownField>().ToList();
            Check(ParameterValue(0) == 7 && dropdowns[0].value == "B", "FX click Redo restores model and control");
            await Task.Delay(100);
            Click(dropdowns[1]);
            Check(ParameterValue(1) == 9, "FX group-header toggle updates the parameter");
            var content = view.Q<VisualElement>(className: "whimtex-fx-parameter-group-content");
            Check(content != null && content.style.display.value != DisplayStyle.None, "FX condition refresh keeps group content visible");
            return "Two-choice dropdown: " + checks + " checks passed, including typed fields, FX body/header and Undo/Redo. Native menu interaction requires manual verification.";
        }
        finally
        {
            window.Close();
            if (fx != null) { Undo.ClearUndo(fx); UnityEngine.Object.DestroyImmediate(fx); }
            if (previousFocus != null) previousFocus.Focus();
        }
    }
}

var type=typeof(DCFApixels.WhimTex.TextureCompositorWindow);
var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public;
DCFApixels.WhimTex.TextureCompositorWindow window=null;
foreach(var existing in UnityEngine.Resources.FindObjectsOfTypeAll<DCFApixels.WhimTex.TextureCompositorWindow>())
    if(existing.name=="Canvas View footer smoke")window=existing;
if(window==null)throw new System.Exception("Run CanvasViewFooterSetup.cs first.");
var root=window.rootVisualElement;var previous=root.userData as UnityEditor.EditorWindow;
int checks=0;void Check(bool value,string label){if(!value)throw new System.Exception(label);checks++;}
UnityEngine.UIElements.VisualElement Find(UnityEngine.UIElements.VisualElement parent,string name)=>UnityEngine.UIElements.UQueryExtensions.Q(parent,name);
try
{
    foreach(int width in new[]{900,700,680,600,599,400,280,200})
    {
        var footer=Find(root,"footer"+width);
        var left=Find(footer,"canvasFooterLeft");var right=Find(footer,"canvasFooterRight");
        var updates=Find(left,"canvasFooterUpdates");var context=Find(left,"canvasFooterContext");
        var inspection=Find(right,"canvasFooterInspection");var color=Find(right,"canvasFooterColor");
        Check(footer.childCount==3&&left.childCount==2&&right.childCount==2,"Two groups per side and central hint");
        Check(updates.childCount==2&&updates[0].ClassListContains("whimtex-canvas-view-quality")&&updates[1].ClassListContains("whimtex-live-output-button"),"Quality and Live Update left");
        Check(((UnityEngine.UIElements.Button)context[0]).text=="Post FX"&&((UnityEngine.UIElements.Button)context[1]).text=="UV","Viewing context left");
        Check(inspection.childCount==3&&((UnityEngine.UIElements.Button)inspection[0]).text=="HDR"&&inspection[1] is UnityEngine.UIElements.FloatField&&inspection[2].ClassListContains("whimtex-debug-button"),"HDR immediately before EV, then Debug");
        Check(color.childCount==4,"RGBA in separate group");
        for(int i=0;i<4;i++)Check(((UnityEngine.UIElements.Button)color[i]).text==new[]{"R","G","B","A"}[i],"RGBA order unchanged");
        bool compact=footer.ClassListContains("whimtex-canvas-view-footer--compact");
        if(width>=700)Check(!compact,"Wide footer stays on one row at "+width);
        if(width<=600)Check(compact,"Compact layout follows the actual control widths at "+width);
        var hint=(UnityEngine.UIElements.Label)footer[1];
        var refreshHint=hint.GetType().GetMethod("RefreshVisibility");
        foreach(string text in new[]{"Add a layer to start",new string('W',300),"", "Ready"})
        {
            hint.text=text;refreshHint.Invoke(hint,null);
            float required=hint.MeasureTextSize(text,0,UnityEngine.UIElements.VisualElement.MeasureMode.Undefined,0,UnityEngine.UIElements.VisualElement.MeasureMode.Undefined).x;
            Check(hint.ClassListContains("whimtex-canvas-view-status--hidden") == (text.Length==0||!(required<=hint.contentRect.width)),"Hide the entire hint only when empty or too wide");
        }
        foreach(var group in new[]{updates,context,inspection,color})
        {
            Check(group.worldBound.xMin>=footer.worldBound.xMin-.1f&&group.worldBound.xMax<=footer.worldBound.xMax+.1f,"Group fits horizontally at "+width+": "+group.name);
            Check(group.worldBound.yMax<=footer.worldBound.yMax+.1f,"Group fits vertically at "+width);
            Check(group.worldBound.yMin>=footer.worldBound.yMin-.1f,"Group starts inside the footer at "+width);
            for(int i=1;i<group.childCount;i++)Check(group[i].worldBound.xMin>=group[i-1].worldBound.xMax-.1f,"Controls do not overlap");
        }
        Check(left.worldBound.xMax<=right.worldBound.xMin+.1f || left.worldBound.yMax<=right.worldBound.yMin+.1f,
            "Sides do not overlap in either layout at "+width);
        if(!compact)
        {
            Check(System.Math.Abs(footer.resolvedStyle.height-26)<.1f,"Normal footer height unchanged");
            Check(left.worldBound.xMax<=right.worldBound.xMin+.1f,"Left/right separated at "+width+": left="+left.worldBound.xMax+", right="+right.worldBound.xMin);
            Check(System.Math.Abs(left.worldBound.center.y-right.worldBound.center.y)<.1f,"Sides on same row");
        }
    }
    return $"Canvas View footer: {checks} checks passed across 900, 700, 680, 600, 599, 400, 280 and 200 px; grouping, order, height and no clipping/overlap.";
}
finally
{
    typeof(UnityEditor.EditorWindow).GetProperty("hasUnsavedChanges").SetValue(window,false);
    type.GetField("temporaryDocumentDirty",f).SetValue(window,false);window.Close();
    if(previous!=null)previous.Focus();
}

var f=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Static;
var type=typeof(DCFApixels.WhimTex.TextureCompositorWindow);var fillType=type.GetNestedType("ContentFillWindow",f);
DCFApixels.WhimTex.TextureCompositorWindow window=null;
foreach(var item in UnityEngine.Resources.FindObjectsOfTypeAll<DCFApixels.WhimTex.TextureCompositorWindow>())if(item.name=="Content fill smoke")window=item;
if(window==null)throw new System.Exception("Run ContentFillUiSetup first.");
UnityEditor.EditorWindow fill=null;
