            Check(Convert.ToBase64String(File.ReadAllBytes(preset)) == Convert.ToBase64String(frozen), "Original preset bytes unchanged");
            UnknownDocument(folder);
        }
        finally
        {
            if (existed) EditorPrefs.SetString(Preference, previous); else EditorPrefs.DeleteKey(Preference);
            string expectedParent = Path.GetFullPath("Temp");
            if (Path.GetDirectoryName(folder) != expectedParent || !Path.GetFileName(folder).StartsWith("WhimTexGradientCleanup_", StringComparison.Ordinal))
                throw new Exception("Unexpected cleanup path");
            if (Directory.Exists(folder)) Directory.Delete(folder, true);
        }
        return "PASS: " + checks + " checks; current formats/HDR/sampling, rejected legacy clipboard/API/brush inputs, frozen 0.12.5 library preset, unknown transition blocks TIFF Save/JSON writer; prefs restored.";
    }
}

// run_script entry RemainingLegacyCleanupSmoke.Run. Only transient owned objects.
using System;
using System.Collections.Generic;
using System.Reflection;
using DCFApixels.WhimTex;
using UnityEngine;

public static class RemainingLegacyCleanupSmoke
{
    const BindingFlags F = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance;
    static readonly Assembly Package = typeof(ShaderFX).Assembly;
    static int checks;
    static void Check(bool value, string message) { if (!value) throw new Exception(message); checks++; }
    static object Field(object value, string name) => value.GetType().GetField(name, F).GetValue(value);
    static void Set(object value, string name, object data) => value.GetType().GetField(name, F).SetValue(value, data);
    static string Code(ShaderFX fx) => (string)Field(fx, "code");
    static List<ShaderFXParameter> Parameters(ShaderFX fx) => (List<ShaderFXParameter>)Field(fx, "parameters");
    static object Call(string type, string method, params object[] args) => Package.GetType("DCFApixels.WhimTex." + type)
        .GetMethod(method, F).Invoke(null, args);
    static void Reject(Action action, string message)
    {
        try { action(); }
        catch (WhimTexDocumentException) { checks++; return; }
        throw new Exception(message);
    }
    public static string Run()
    {
        checks = 0;
        Check(typeof(ShaderFXParameter).GetField("declaredInCode", F) == null, "No manual/code mode flag");
        Check(Package.GetType("DCFApixels.WhimTex.ShaderFXParameterDrawer") == null, "No manual drawer");
        Check(typeof(TextureCompositorWindow).GetField("documentFilePath", F) == null &&
            typeof(TextureCompositorWindow).GetField("documentFileGuid", F) == null &&
            typeof(TextureCompositorWindow).GetField("documentFileOwner", F) == null, "No duplicated window binding");
        foreach (string kind in new[] { "document", "fragment", "layers" })
            Reject(() => WhimTexDocumentJson.Read("{\"format\":\"whimtex.document\",\"version\":1,\"kind\":\"" + kind + "\",\"layers\":[]}", false).Dispose(), "Root kind accepted");
        const string oldAxes = "{\"format\":\"whimtex.document\",\"version\":1,\"layers\":[" +
            "{\"id\":\"noise\",\"behaviour\":{\"$type\":\"NoiseLayerBehaviour\",\"scale\":23,\"warpScale\":3}}," +
            "{\"id\":\"pattern\",\"behaviour\":{\"$type\":\"ColorFillLayerBehaviour\",\"pattern\":{\"size\":37}}}," +
            "{\"id\":\"shape\",\"behaviour\":{\"$type\":\"ShapeLayerBehaviour\",\"roundness\":0.4,\"cornerRoundness\":[-1,0.2,-1,0]}}]}";
        using (var read = WhimTexDocumentJson.Read(oldAxes, false))
        {
            var noise = (NoiseLayerBehaviour)read.Document.layers[0].Behaviour;
            var pattern = ((ColorFillLayerBehaviour)read.Document.layers[1].Behaviour).pattern;
            var shape = (ShapeLayerBehaviour)read.Document.layers[2].Behaviour;
            Check(noise.scaleY == 23 && noise.warpScaleY == 3, "Omitted Compact axes normalized");
            Check(pattern.sizeY == 37, "Pattern omitted axis normalized");
            Check(shape.cornerRoundness == new Vector4(.4f, .2f, .4f, 0), "Each inherited corner normalized independently");
            foreach (WhimTexJsonWriteMode mode in Enum.GetValues(typeof(WhimTexJsonWriteMode)))
            {
                var written = WhimTexDocumentJson.Write(read.Document, new WhimTexJsonWriteOptions { Mode = mode });
                using var again = WhimTexDocumentJson.Read(written.Json, false);
                Check(((NoiseLayerBehaviour)again.Document.layers[0].Behaviour).Scale == noise.Scale, "Explicit axes roundtrip " + mode);
                Check(((ShapeLayerBehaviour)again.Document.layers[2].Behaviour).cornerRoundness == shape.cornerRoundness, "Explicit corners roundtrip " + mode);
            }
        }
        Check(new NoiseLayerBehaviour().scaleY == 8 && new NoiseLayerBehaviour().warpScaleY == 1, "New Noise explicit defaults");
        Check(new FillPatternSettings().sizeY == 64 && new ShapeLayerBehaviour().cornerRoundness == Vector4.zero, "New Pattern/Shape explicit defaults");

        foreach (bool declared in new[] { false, true })
        {
            const string removed = "float4 ApplyFX(float2 uv, float4 color) { return color; }";
            string json = "{\"format\":\"whimtex.document\",\"version\":1,\"layers\":[{\"id\":\"fx-layer\",\"behaviour\":{\"$type\":\"ColorFillLayerBehaviour\"},\"modifiers\":[{\"$type\":\"ShaderFX\",\"code\":\"" + removed +
                "\",\"parameters\":[{\"name\":\"_Removed\",\"type\":\"Float\",\"floatValue\":0.625,\"declaredInCode\":" + (declared ? "true" : "false") + "}]}]}]}";
            using var read = WhimTexDocumentJson.Read(json, false);
            var effect = (ShaderFX)read.Document.layers[0].modifiers[0];
            Check(Parameters(effect).Count == (declared ? 0 : 1), "Only saved manual definitions are converted; declared=" + declared);
            if (declared) Check(Code(effect) == removed, "A removed 0.12.5 code declaration is not resurrected");
            else
            {
                Set(effect, "code", removed);
                string jsonDraft = WhimTexDocumentJson.Write(read.Document).Json;
                using var again = WhimTexDocumentJson.Read(jsonDraft, false);
                Check(Parameters((ShaderFX)again.Document.layers[0].modifiers[0]).Count == 0, "New JSON does not restore an unapplied declaration deletion");
                Check(Parameters(effect).Count == 1, "JSON writing does not mutate the pending authoring state");
            }
        }

        // Simulate the named-field 0.12.5 model without regenerating any frozen fixture.
        var source = ScriptableObject.CreateInstance<ShaderFX>();
        ShaderFX loaded = null;
        ShaderFX copied = null;
        var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false, true);
        texture.SetPixels(new[] { Color.red, Color.green, Color.blue, Color.white }); texture.Apply();
        texture.filterMode = FilterMode.Point; texture.wrapModeU = TextureWrapMode.Repeat;
        var saved = new List<ShaderFXParameter>();
        try
        {
            foreach (ShaderFXParameterType type in Enum.GetValues(typeof(ShaderFXParameterType)))
            {
                var p = new ShaderFXParameter { name = "_Saved" + type, type = type, floatValue = .625f,
                    colorValue = new Color(2, -.2f, .4f, .3f), vectorValue = new Vector4(.2f, .7f, -.4f, 8),
                    textureValue = type == ShaderFXParameterType.Texture2D ? texture : null,
                    transformValue = new ShaderFXTransform { position = new Double2(.2, .8), size = new Double2(.7, 1.2), rotation = 31 },
                    gradientValue = new WhimTexGradient(),
                    curveValue = new AnimationCurve(new Keyframe(0, 2), new Keyframe(.3f, -.7f), new Keyframe(1, 3)) };
                p.gradientValue.SetKeys(new[] { new GradientColorKey(Color.red, 0), new GradientColorKey(Color.green, .4f), new GradientColorKey(Color.blue, 1) },
                    new[] { new GradientAlphaKey(.2f, 0), new GradientAlphaKey(.8f, 1) });
                saved.Add(p);
            }
            Set(source, "code", "// @whimtex-effect Tests/Saved\nfloat4 ApplyFX(float2 uv, float4 color) { return color; }");
            Set(source, "parameters", saved);
            using var container = new WhimTexDocumentContainer();
            byte[] bytes = (byte[])Call("WhimTexDocumentSerializer", "Serialize", source, container);
            var read = Call("WhimTexDocumentSerializer", "Deserialize", bytes, container, typeof(ShaderFX), null, false);
            loaded = (ShaderFX)read.GetType().GetProperty("Model", F).GetValue(read);
            Check(Parameters(loaded).Count == saved.Count, "All saved parameter types declared");
            Check(Code(loaded).StartsWith("// @whimtex-effect Tests/Saved\n"), "Header preserved");
            foreach (var old in saved)
            {
                var modern = Parameters(loaded).Find(p => p.name == old.name);
                Check(modern != null && modern.id == old.id && modern.controls.Count == 1, "Declaration and stable ID " + old.type);
                Check(modern.floatValue == old.floatValue && modern.colorValue == old.colorValue && modern.vectorValue == old.vectorValue, "Values " + old.type);
                Check(modern.gradientValue.Equals(old.gradientValue) && modern.curveValue.Equals(old.curveValue), "Arbitrary gradient/curve " + old.type);
                Check(modern.transformValue.position == old.transformValue.position && modern.transformValue.size == old.transformValue.size && modern.transformValue.rotation == old.transformValue.rotation, "Transform " + old.type);
            }
            var image = Parameters(loaded).Find(p => p.type == ShaderFXParameterType.Texture2D).textureValue;
            Check(image != null && image.filterMode == texture.filterMode && image.wrapModeU == texture.wrapModeU && image.GetPixel(0, 0) == Color.red, "Texture value and sampling");
            string canonical = Code(loaded);
            using var nextContainer = new WhimTexDocumentContainer();
            byte[] next = (byte[])Call("WhimTexDocumentSerializer", "Serialize", loaded, nextContainer);
            var nextRead = Call("WhimTexDocumentSerializer", "Deserialize", next, nextContainer, typeof(ShaderFX), null, false);
            copied = (ShaderFX)nextRead.GetType().GetProperty("Model", F).GetValue(nextRead);
            Check(Code(copied) == canonical && Parameters(copied).Count == saved.Count, "Conversion idempotent");
            Check(((IReadOnlyList<string>)nextRead.GetType().GetProperty("SkippedFields", F).GetValue(nextRead)).Count == 0, "No lost/unknown fields");
            return "PASS: remaining legacy cleanup checks=" + checks + "; explicit axes/corners, root kind rejection, all 13 saved FX types/IDs/values, arbitrary curves/gradients, texture sampling and idempotence.";
        }
        finally
        {
            foreach (var fx in new[] { loaded, copied })
            {
                if (fx == null) continue;
                var image = Parameters(fx).Find(p => p.type == ShaderFXParameterType.Texture2D)?.textureValue;
                if (image != null && image != texture) UnityEngine.Object.DestroyImmediate(image);
                UnityEngine.Object.DestroyImmediate(fx);
            }
            UnityEngine.Object.DestroyImmediate(source); UnityEngine.Object.DestroyImmediate(texture);
        }
    }
}

// run_script UserSettingsCleanupSmoke.Run. Restores every touched preference/cache and owns only
// transient windows and a unique Temp directory; never opens or edits user documents/presets.
using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using UnityEditor;
using UnityEngine;
using DCFApixels.WhimTex;
using Object = UnityEngine.Object;

public static class UserSettingsCleanupSmoke
{
    const BindingFlags F = BindingFlags.Static | BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
    static readonly Type Settings = typeof(TextureCompositorWindow).Assembly.GetType("DCFApixels.WhimTex.WhimTexUserSettings", true);
    static int checks;
    sealed class Preference
    {
        internal string key, kind;
        internal bool exists;
        internal object value;
        internal Preference(string key, string kind)
        {
            this.key = key; this.kind = kind; exists = EditorPrefs.HasKey(key);
            value = kind == "int" ? (object)EditorPrefs.GetInt(key) : kind == "bool" ? EditorPrefs.GetBool(key) :
                kind == "float" ? EditorPrefs.GetFloat(key) : EditorPrefs.GetString(key);
        }
        internal void Restore()
        {
            if (!exists) EditorPrefs.DeleteKey(key);
            else if (kind == "int") EditorPrefs.SetInt(key, (int)value);
            else if (kind == "bool") EditorPrefs.SetBool(key, (bool)value);
            else if (kind == "float") EditorPrefs.SetFloat(key, (float)value);
            else EditorPrefs.SetString(key, (string)value);
        }
    }
    static void Check(bool ok, string message) { checks++; if (!ok) throw new Exception(message); }
    static string Key(Type type, string field) => (string)type.GetField(field, F).GetRawConstantValue();
    static object Read(object obj, string field) => obj.GetType().GetField(field, F).GetValue(obj);
    static object Call(object obj, string method, params object[] args) =>
        (obj as Type ?? obj.GetType()).GetMethod(method, F).Invoke(obj is Type ? null : obj, args);
    static string Folder() => (string)Settings.GetProperty("PresetsFolder", F).GetValue(null);
    public static string Run()
    {
        checks = 0;
        var preferences = new List<Preference>();
        var windows = new List<TextureCompositorWindow>();
        var caches = new Dictionary<FieldInfo, object>();
        void Remember(string key, string kind) => preferences.Add(new Preference(key, kind));
        var appearance = new[] {
            ("LightKey", "CheckerLight", "string"), ("DarkKey", "CheckerDark", "string"),
            ("ErrorKey", "InvalidPixels", "string"), ("SizeKey", "CheckerSize", "int"),
            ("ShowMantaKey", "ShowManta", "bool"), ("PostFxBackgroundKey", "PostFxBackground", "string"),
            ("PostFxBackgroundModeKey", "PostFxBackgroundMode", "int")
        };
        string temp = Path.GetFullPath(Path.Combine(Application.dataPath, "../Temp"));
        string root = Path.Combine(temp, "WhimTexSettingsCleanup_" + Guid.NewGuid().ToString("N"));
        string folderKey = Key(Settings, "PresetsFolderKey");
        var windowType = typeof(TextureCompositorWindow);
        string toolKey = Key(windowType, "CanvasToolPrefKey");
        string returnKey = Key(windowType, "CanvasTransformReturnToolPrefKey");
        string scaleKey = Key(windowType, "PaintingCanvasScalePrefKey");
        string paintKey = Key(windowType, "PaintToolSettingsPrefKey");
        const string oldTool = "DCFApixels.WhimTex.PreviewTool";
        const string oldReturn = "DCFApixels.WhimTex.PreviewTransformReturnTool";
        const string oldScale = "DCFApixels.WhimTex.PaintingPreviewScale";
        const string oldPaint = "DCFApixels.WhimTex.PaintToolSettings";
        foreach (var spec in appearance)
        {
            Remember(Key(Settings, spec.Item1), spec.Item3);
            Remember("DCFApixels.WhimTex.Preview." + spec.Item2, spec.Item3);
        }
        foreach (string key in new[] { toolKey, returnKey, paintKey, oldTool, oldReturn, oldPaint, folderKey,
            Key(Settings, "HealingStrokeColorKey") }) Remember(key, "string");
        Remember(scaleKey, "float"); Remember(oldScale, "float");
        foreach (string name in new[] { "checkerSize", "checkerLight", "checkerDark", "invalidPixels",
            "postFxBackground", "postFxBackgroundMode", "showManta", "healingStrokeColor" })
        {
            var field = Settings.GetField(name, F);
            caches[field] = field.GetValue(null);
        }
        try
        {
            foreach (var spec in appearance)
            {
                string key = Key(Settings, spec.Item1);
                string old = "DCFApixels.WhimTex.Preview." + spec.Item2;
                Check(key == "DCFApixels.WhimTex.CanvasView." + spec.Item2, "Canvas View key: " + spec.Item2);
                if (spec.Item3 == "int") EditorPrefs.SetInt(old, 73);
                else if (spec.Item3 == "bool") EditorPrefs.SetBool(old, false);
                else EditorPrefs.SetString(old, "#112233");
            }
            Check(toolKey == "DCFApixels.WhimTex.Canvas.Tool" &&
                returnKey == "DCFApixels.WhimTex.Canvas.TransformReturnTool" &&
                scaleKey == "DCFApixels.WhimTex.Canvas.PaintingScale" &&
                paintKey == "DCFApixels.WhimTex.Canvas.PaintToolSettings", "Canonical Canvas keys");
            Call(Settings, "ResetCanvasViewAppearance");
            Check((int)Settings.GetProperty("CheckerSize", F).GetValue(null) == 16 &&
                (bool)Settings.GetProperty("ShowManta", F).GetValue(null), "Old appearance values are not restored");
            Settings.GetProperty("CheckerSize", F).SetValue(null, 29);
            Check(EditorPrefs.GetInt(Key(Settings, "SizeKey")) == 29, "Size uses current key");
            Settings.GetProperty("CheckerLight", F).SetValue(null, new Color(.2f, .4f, .6f));
            Check(EditorPrefs.GetString(Key(Settings, "LightKey")) == "#336699", "Color uses current key");
            Settings.GetProperty("ShowManta", F).SetValue(null, false);
            Check(EditorPrefs.HasKey(Key(Settings, "ShowMantaKey")) && !EditorPrefs.GetBool(Key(Settings, "ShowMantaKey")),
                "Background visibility uses current key");
            Call(Settings, "ResetCanvasViewAppearance");
            foreach (var spec in appearance)
            {
                Check(!EditorPrefs.HasKey(Key(Settings, spec.Item1)), "Reset removes current key: " + spec.Item2);
                string old = "DCFApixels.WhimTex.Preview." + spec.Item2;
                Check(spec.Item3 == "int" ? EditorPrefs.GetInt(old) == 73 :
                    spec.Item3 == "bool" ? !EditorPrefs.GetBool(old) : EditorPrefs.GetString(old) == "#112233",
                    "Historical settings not migrated or rewritten: " + spec.Item2);
            }
            EditorPrefs.SetString(oldTool, "Brush"); EditorPrefs.SetString(oldReturn, "Pencil");
            EditorPrefs.SetFloat(oldScale, .125f);
            EditorPrefs.SetString(oldPaint, "{\"brushSize\":913,\"blurOpacity\":0.13}");
            foreach (string key in new[] { toolKey, returnKey, scaleKey, paintKey }) EditorPrefs.DeleteKey(key);
            var window = ScriptableObject.CreateInstance<TextureCompositorWindow>(); windows.Add(window);
            Check(Read(window, "canvasTool").ToString() == "None" &&
                Read(window, "canvasTransformReturnTool").ToString() == "None", "Old tool selections ignored");
            Check((float)Read(window, "paintingCanvasScale") == 1f, "Old quality setting ignored");
            Check((float)Read(Read(window, "paintSettings"), "brushSize") == 32f, "Old paint settings ignored");
            EditorPrefs.SetString(toolKey, "Brush"); EditorPrefs.SetString(returnKey, "Pencil");
            EditorPrefs.SetFloat(scaleKey, .25f);
            EditorPrefs.SetString(paintKey, "{\"brushSize\":57,\"blurFlow\":0.23}");
            var restored = ScriptableObject.CreateInstance<TextureCompositorWindow>(); windows.Add(restored);
            Check(Read(restored, "canvasTool").ToString() == "Brush" &&
                Read(restored, "canvasTransformReturnTool").ToString() == "Pencil", "Current tools reload");
            Check((float)Read(restored, "paintingCanvasScale") == .25f, "Current quality reloads");
            var paint = Read(restored, "paintSettings");
            Check((float)Read(paint, "brushSize") == 57f && (float)Read(paint, "blurFlow") == .23f,
                "Current paint settings reload");
            Call(restored, "SavePaintToolSettings");
            string saved = EditorPrefs.GetString(paintKey);
            Check(saved.Contains("\"blurFlow\"") && !saved.Contains("\"blurOpacity\""), "Only current paint fields are written");
            foreach (string source in new[] { "{\"blurOpacity\":0.13}", "[" })
            {
                EditorPrefs.SetString(paintKey, source);
                windowType.GetField("paintSettings", F).SetValue(restored, null);
                Call(restored, "LoadPaintToolSettings");
                Check((float)Read(Read(restored, "paintSettings"), "blurFlow") == 1f,
                    "No blurOpacity migration; malformed settings safely fall back");
            }
            Directory.CreateDirectory(root);
            const string baseline = "Packages/com.dcfapixels.whimtex/Tests~/Fixtures/Compatibility0125/";
            string brush = Path.Combine(root, "brush.sebrush");
            File.Copy(baseline + "brush.sebrush", brush);
            byte[] bytes = File.ReadAllBytes(brush);
            object[] args = { root, null };
            Check((bool)Settings.GetMethod("TrySetPresetsFolder", F).Invoke(null, args) && args[1] == null && Folder() == root,
                "Explicit library folder remains supported");
            Call(Settings, "ResetCanvasViewAppearance");
            Check(Folder() == root, "Appearance reset does not reset library folder");
            string canonical = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "DCFApixels", "WhimTex", "Presets");
            bool existed = Directory.Exists(canonical);
            Call(Settings, "ResetPresetsFolder");
            Check(Folder() == canonical && Directory.Exists(canonical) == existed, "Default path is canonical and not created");
            Check(Convert.ToBase64String(File.ReadAllBytes(brush)) == Convert.ToBase64String(bytes),
                "Reset does not move/delete/rewrite 0.12.5 preset files");
            string missing = Path.Combine(root, "NotCreated");
            args = new object[] { missing, null };
            Check((bool)Settings.GetMethod("TrySetPresetsFolder", F).Invoke(null, args) && !Directory.Exists(missing),
                "Selecting missing absolute directory does not create it");
            args = new object[] { brush, null };
            Check(!(bool)Settings.GetMethod("TrySetPresetsFolder", F).Invoke(null, args) && Folder() == missing,
                "File path rejected without replacing existing setting");
            args = new object[] { "relative-folder", null };
            Check(!(bool)Settings.GetMethod("TrySetPresetsFolder", F).Invoke(null, args) && Folder() == missing,
                "Relative path rejected without replacing existing setting");
            return "PASS: " + checks + " user-settings checks; canonical keys, no settings migration, reload/reset, folder validation and unchanged 0.12.5 preset bytes.";
        }
        catch (TargetInvocationException e) { throw e.InnerException ?? e; }
        finally
        {
            foreach (var window in windows) if (window != null) Object.DestroyImmediate(window);
            foreach (var item in caches) item.Key.SetValue(null, item.Value);
            for (int i = preferences.Count - 1; i >= 0; i--) preferences[i].Restore();
            (Settings.GetField("Changed", F).GetValue(null) as Action)?.Invoke();
            if (Directory.Exists(root) && Path.GetDirectoryName(root) == temp &&
                Path.GetFileName(root).StartsWith("WhimTexSettingsCleanup_", StringComparison.Ordinal))
                Directory.Delete(root, true);
        }
    }
}
